{"path": "/tmp/sv-88953a3aeaf34131a38d0b8d883a47c9/Components/Pages/Chat/ChatPage.razor", "file_text": "@page "/chat"
@using sv_88953a3aeaf34131a38d0b8d883a47c9.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(isThreadOpen ? "thread-open" : "")">
        <MessageArea ChannelName="@selectedChannelName"
                     ChannelDescription="@selectedChannelDescription"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnReplyClicked="OpenThread"
                     OnReactionAdded="AddReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="CloseThread"
                     OnReplySent="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadMessages = [];
    private Dictionary<int, int> threadReplyCounts = new();
    private Message? threadRootMessage;

    private int selectedChannelId;
    private string selectedChannelName = "";
    private string selectedChannelDescription = "";
    private bool isThreadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannelId = channel.Id;
        selectedChannelName = channel.Name;
        selectedChannelDescription = channel.Description;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        await UpdateThreadCounts();
        CloseThreadSync();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task CloseThread()
    {
        CloseThreadSync();
        await Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);
        await UpdateThreadCounts();
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messageSkip > 0 ? messageSkip : PageSize);
    }

    private async Task UpdateThreadCounts()
    {
        // Build thread reply counts from messages that are replies
        threadReplyCounts = new Dictionary<int, int>();
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            threadReplyCounts.TryGetValue(rootId, out var count);
            threadReplyCounts[rootId] = count + 1;
        }
        await Task.CompletedTask;
    }
}
"}

