+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 3px;
+    font-size: 0.85rem;
+    transition: background 0.1s;
+}
+
+::deep .action-btn:hover {
+    background: #4f545c;
+}
+
+::deep .emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 8px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+    z-index: 10;
+}
+
+::deep .emoji-option {
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+    font-size: 1.1rem;
+    transition: background 0.1s;
+}
+
+::deep .emoji-option:hover {
+    background: #4f545c;
+}
+
+/* Message input */
+::deep .message-input-area,
+::deep .thread-input-area {
+    display: flex;
+    gap: 8px;
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .message-input,
+::deep .thread-input {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 12px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+::deep .message-input:focus,
+::deep .thread-input:focus {
+    outline: none;
+    box-shadow: 0 0 0 2px #5865f2;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+    transition: background 0.15s;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+    height: 100vh;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    color: #fff;
+    font-size: 1rem;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #8e9297;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+::deep .thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #3a3d42;
+}
+
+::deep .thread-reply:last-child {
+    border-bottom: none;
+}
+

